-- Column names and exact types of every source table the Temporal Self chronicle reads, taken
-- read-only from the live conjourney database on 2026-10-10 (information_schema + format_type).
-- Constraints and indexes are dropped on purpose: the replay eval loads cut-down fixture rows.
-- ORION-MIGRATION-NOT-A-MIGRATION: eval fixture, never applied to a real database.
CREATE TABLE IF NOT EXISTS attention_loop_outcome (outcome_id text, loop_id text, theme_key text, verdict text, actor text, note text, salience_at_close double precision, weights_version text, features_at_close jsonb, created_at timestamp with time zone, enqueued_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS attention_salience_trace (trace_id text, loop_id text, theme_key text, description text, correlation_id text, salience double precision, weights_version text, scope text, features jsonb, created_at timestamp with time zone, enqueued_at timestamp with time zone, why_it_matters text, target_type text);
CREATE TABLE IF NOT EXISTS cabinet_ambient_spike (spike_id character varying, correlation_id character varying, node character varying, "timestamp" timestamp with time zone, created_at timestamp with time zone, activity double precision, rms double precision, peak double precision, activity_threshold double precision, consecutive_ticks integer, source_service character varying, source_node character varying);
CREATE TABLE IF NOT EXISTS chat_history_log (id character varying, correlation_id character varying, source character varying, prompt text, response text, user_id character varying, session_id character varying, spark_meta jsonb, memory_status character varying, memory_tier character varying, memory_reason character varying, thought_process text, client_meta jsonb, llm_uncertainty_source character varying, llm_mean_logprob double precision, llm_min_logprob double precision, llm_mean_top1_margin double precision, llm_low_margin_token_count integer, llm_low_logprob_token_count integer, llm_unstable_span_count integer, llm_uncertainty_available boolean, created_at timestamp without time zone, response_identity text);
CREATE TABLE IF NOT EXISTS curiosity_offer_decisions (run_id text, decided_at timestamp with time zone, arm text, value_arm_propensity double precision, offered jsonb, stale_offered jsonb, material_ids jsonb, constants jsonb, turn_snapshot jsonb, turn_started_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS curiosity_run_outcomes (run_id text, completed_at timestamp with time zone, turn_ok boolean, realized_nats double precision, unknown_reason text, n_tested integer, n_moved integer, n_formed integer, n_moved_untested integer, n_unattributed integer, n_invalid_confidence integer, per_prior jsonb, revision_agreement double precision);
CREATE TABLE IF NOT EXISTS dream_cycle (cycle_id text, trigger text, status text, started_at timestamp with time zone, ended_at timestamp with time zone, pressure double precision, replay_count integer, hypothesis_count integer, no_link_count integer, unparseable_count integer, llm_failures integer, compaction_delta_id text, cycle_json jsonb, enqueued_at timestamp with time zone);
CREATE TABLE IF NOT EXISTS dream_hypothesis (hypothesis_id text, cycle_id text, arm text, claim text, why text, ref_a text, ref_b text, created_at timestamp with time zone, expires_at timestamp with time zone, offered_at timestamp with time zone, offered_run_id text);
