CREATE TABLE IF NOT EXISTS field_dominance_run (run_id text, target_id text, target_kind text, started_at timestamp with time zone, ended_at timestamp with time zone, tick_count integer, min_streak_at_run integer, first_source_attention_frame_id text, last_source_attention_frame_id text, left_censored boolean);
