CREATE TABLE IF NOT EXISTS substrate_attention_schema (entry_id character varying, created_at timestamp with time zone, generated_at timestamp with time zone, process character varying, correlation_id character varying, attended_id character varying, attended_label character varying, attention_reason character varying, reason_narrative text, narrative_kind character varying, confidence double precision, confidence_basis character varying, predicted_next text);
